for col in df.columns:
    dtype_str = dtypes.get(col, "object")
    try:
        if dtype_str.startswith("pd/i") and not any(c.isdigit() for c in dtype_str[3:]):
            # Legacy numeric tag without width: allow widening but preserve kind
            # We can't know the original width, so we let numpy/pandas infer it from data
            # but we ensure it's at least an integer.
            df[col] = pd.to_numeric(df[col], errors='coerce').astype('int64')
        elif dtype_str.startswith("pd/u") and not any(c.isdigit() for c in dtype_str[3:]):
            df[col] = pd.to_numeric(df[col], errors='coerce').astype('uint64')
        elif dtype_str.startswith("pd/f") and not any(c.isdigit() for c in dtype_str[3:]):
            df[col] = pd.to_numeric(df[col], errors='coerce').astype('float64')
        elif dtype_str == "pd/in" and not any(c.isdigit() for c in dtype_str[3:]):
            # pd/in is likely for integer-like indices or similar
            df[col] = pd.to_numeric(df[col], errors='coerce').astype('int64')
        else:
            dtype = np.dtype(dtype_str)
            df[col] = df[col].astype(dtype)
    except Exception:
        msg = (
            f"jsonpickle was unable to properly deserialize "
            f"the column {col} into its inferred dtype. "
            f"Please file a bugreport on the jsonpickle GitHub! "
        )
        warnings.warn(msg)

